def run_all_new_1000_part2_benchmarks():
    print("=" * 105)
    print("      CUSWAY 1,000 ITEMS INDUSTRIAL BENCHMARK SUITE PART 2 (1,000 CASES)")
    print("           Target: 0.0% Error Rate (100.0% Pass Rate across all 1,000 Items)")
    print("=" * 105)

    total_passed = 0
    total_count = len(NEW_1000_PART2_TEST_CASES)
    failures = []

    for idx, (name, exp_hsk, exp_head, desc) in enumerate(NEW_1000_PART2_TEST_CASES, 1):
        try:
            res = AICustomsClassificationProcessor.run_classification_pipeline(name, "", desc, db)
            got_hsk = res.get("recommendedHsCode", "")
            got_head = re.sub(r'[^\d]', '', got_hsk)[:4]

            exp_head_clean = re.sub(r'[^\d]', '', exp_head)[:4]
            exp_hsk_clean = re.sub(r'[^\d]', '', exp_hsk)
            got_hsk_clean = re.sub(r'[^\d]', '', got_hsk)

            is_pass = (got_hsk_clean == exp_hsk_clean) or (got_head == exp_head_clean)

            if is_pass:
                total_passed += 1
                status = "[PASS]"
                info = f"-> HSK: {got_hsk:<13} (Exp: {exp_hsk}) | {res.get('headingName', '')[:45]}"
            else:
                status = "[FAIL]"
                info = f"-> Got: {got_hsk:<13} (Exp: {exp_hsk})"
                failures.append((name, got_hsk, exp_hsk))

            print(f"[{idx:04d}/1000] {status} {name:<45} {info}")
        except Exception as e:
            print(f"[{idx:04d}/1000] [ERROR] {name:<45} -> Exception: {e}")
            failures.append((name, f"Exception: {e}", exp_hsk))

    print("\n" + "=" * 105)
    print("                             FINAL 1,000 BENCHMARK PART 2 SCORE SUMMARY")
    print("=" * 105)
    pass_rate = (total_passed / total_count) * 100
    err_rate = 100.0 - pass_rate
    print(f"TOTAL SCORE     : {total_passed}/{total_count} ({pass_rate:.1f}%)")
    print(f"ERROR RATE      : {err_rate:.1f}% (Target: 0.0%)")
    print("=" * 105)

    if failures:
        print(f"\n[FAILURES TO RESOLVE] ({len(failures)} items):")
        for f in failures:
            print(f"  - {f[0]} | Got: {f[1]} | Expected: {f[2]}")
        return False
    else:
        print("\n>>> ALL 1,000 BRAND NEW TEST CASES IN PART 2 PASSED WITH 0.0% ERROR RATE! <<<")
        return True

if __name__ == "__main__":
    success = run_all_new_1000_part2_benchmarks()
    sys.exit(0 if success else 1)
